Here's a self-contained solar system simulation with a glowing sun, six planets at varying orbital radii and speeds, a twinkling starfield, and subtle orbit trails — all rendered on a single canvas with `requestAnimationFrame`:```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Solar System</title>
<style>
  html, body { margin: 0; height: 100%; background: #000; overflow: hidden; }
  canvas { display: block; }
</style>
</head>
<body>
<canvas id="sky"></canvas>
<script>
const canvas = document.getElementById('sky');
const ctx = canvas.getContext('2d');
let W, H, cx, cy;

function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
  cx = W / 2;
  cy = H / 2;
}
window.addEventListener('resize', resize);
resize();

/* ---------- Starfield ---------- */
const stars = [];
for (let i = 0; i < 220; i++) {
  stars.push({
    x: Math.random(),
    y: Math.random(),
    r: Math.random() * 1.3 + 0.3,
    tw: Math.random() * Math.PI * 2,      // twinkle phase
    sp: Math.random() * 0.02 + 0.004      // twinkle speed
  });
}

/* ---------- Sun ---------- */
function drawSun(t) {
  const pulse = 1 + Math.sin(t * 0.002) * 0.06;

  // Outer corona glow
  let g = ctx.createRadialGradient(cx, cy, 0, cx, cy, 90 * pulse);
  g.addColorStop(0.00, 'rgba(255,240,200,1)');
  g.addColorStop(0.25, 'rgba(255,200,80,0.85)');
  g.addColorStop(0.55, 'rgba(255,140,40,0.35)');
  g.addColorStop(1.00, 'rgba(255,100,20,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, 90 * pulse, 0, Math.PI * 2);
  ctx.fill();

  // Core
  g = ctx.createRadialGradient(cx, cy, 0, cx, cy, 26 * pulse);
  g.addColorStop(0, '#fffbe8');
  g.addColorStop(0.7, '#ffd257');
  g.addColorStop(1, '#ff9a2e');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, 26 * pulse, 0, Math.PI * 2);
  ctx.fill();
}

/* ---------- Planets ---------- */
const planets = [
  { name:'Mercury', dist: 70,  size: 4,  speed: 0.0042, color:'#b9a48f', trail: 18 },
  { name:'Venus',   dist: 105, size: 7,  speed: 0.0031, color:'#e8c98a', trail: 14 },
  { name:'Earth',   dist: 145, size: 8,  speed: 0.0023, color:'#5aa9e6', trail: 12 },
  { name:'Mars',    dist: 185, size: 5.5,speed: 0.0017, color:'#e07b4f', trail: 10 },
  { name:'Jupiter', dist: 245, size: 15, speed: 0.0009, color:'#d8b48a', trail: 7  },
  { name:'Saturn',  dist: 310, size: 12, speed: 0.0006, color:'#e6d5a8', trail: 5, ring: true }
];

// Random starting angles so planets aren't aligned
planets.forEach(p => p.angle = Math.random() * Math.PI * 2);

function drawPlanets(t) {
  planets.forEach(p => {
    p.angle += p.speed;

    // Faint orbit path
    ctx.strokeStyle = 'rgba(255,255,255,0.07)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, p.dist, 0, Math.PI * 2);
    ctx.stroke();

    const x = cx + Math.cos(p.angle) * p.dist;
    const y = cy + Math.sin(p.angle) * p.dist;

    // Motion trail (arc fading behind the planet)
    ctx.strokeStyle = p.color;
    ctx.globalAlpha = 0.35;
    ctx.lineWidth = p.size * 0.5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.arc(cx, cy, p.dist, p.angle - 0.35, p.angle, false);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // Saturn's ring behind
    if (p.ring) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(-0.45);
      ctx.scale(1, 0.35);
      ctx.strokeStyle = 'rgba(230,213,168,0.75)';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, p.size * 1.9, Math.PI * 0.05, Math.PI * 0.95);
      ctx.stroke();
      ctx.restore();
    }

    // Shaded sphere: light side faces the sun
    const lx = -Math.cos(p.angle), ly = -Math.sin(p.angle);
    const g = ctx.createRadialGradient(
      x + lx * p.size * 0.45, y + ly * p.size * 0.45, p.size * 0.1,
      x, y, p.size * 1.15
    );
    g.addColorStop(0, p.color);
    g.addColorStop(0.6, shade(p.color, -0.35));
    g.addColorStop(1, shade(p.color, -0.75));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, p.size, 0, Math.PI * 2);
    ctx.fill();

    // Saturn's ring in front
    if (p.ring) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(-0.45);
      ctx.scale(1, 0.35);
      ctx.strokeStyle = 'rgba(230,213,168,0.9)';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, p.size * 1.9, Math.PI * 1.05, Math.PI * 1.95);
      ctx.stroke();
      ctx.restore();
    }
  });
}

/* Simple hex shading helper */
function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  r = Math.max(0, Math.min(255, Math.round(r + 255 * amt)));
  g = Math.max(0, Math.min(255, Math.round(g + 255 * amt)));
  b = Math.max(0, Math.min(255, Math.round(b + 255 * amt)));
  return `rgb(${r},${g},${b})`;
}

/* ---------- Main loop ---------- */
function frame(t) {
  // Semi-transparent fill for subtle motion trails on stars/planets
  ctx.fillStyle = 'rgba(2,4,10,0.35)';
  ctx.fillRect(0, 0, W, H);

  // Stars (twinkle)
  stars.forEach(s => {
    s.tw += s.sp;
    const a = 0.35 + Math.sin(s.tw) * 0.35;
    ctx.fillStyle = `rgba(255,255,255,${a})`;
    ctx.beginPath();
    ctx.arc(s.x * W, s.y * H, s.r, 0, Math.PI * 2);
    ctx.fill();
  });

  drawSun(t);
  drawPlanets(t);

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
</script>
</body>
</html>
```**How it works:**

- **Sun** — a pulsing core wrapped in a layered radial-gradient corona that gently breathes over time.
- **Six planets** — Mercury through Saturn, each with its own orbital radius, angular speed (inner planets orbit faster, matching Kepler-ish intuition), size, and color. Saturn gets a tilted ring drawn in two passes so it correctly passes *behind* and *in front* of the planet.
- **Shading** — each planet uses a radial gradient offset toward the sun, so the lit hemisphere always faces the Sun as it orbits.
- **Trails** — each planet drags a short fading arc behind it, and a semi-transparent canvas fill adds a soft global motion blur.
- **Starfield** — 220 stars twinkling at independent phases and speeds.
- **Motion** — a single `requestAnimationFrame` loop drives everything; the canvas resizes responsively with the window.
